package org.pocketlore.app;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Supplemental actual source-button check; no model generation and no generated-link credit. */
public final class SourceLibraryInstrumentation extends Instrumentation {
 MainActivity a;File root;JSONObject report=new JSONObject();JSONArray dialogs=new JSONArray();
 Object field(Object o,String n){return AnswerLibraryInstrumentation.field(o,n);}void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 void await(java.util.function.BooleanSupplier f)throws Exception{long end=System.nanoTime()+60_000_000_000L;while(!f.getAsBoolean()&&System.nanoTime()<end)Thread.sleep(20);check(f.getAsBoolean(),"UI timeout");}
 void ready()throws Exception{await(()->{boolean[] b={false};runOnMainSync(()->b[0]=!(Boolean)field(a,"searching")&&!(Boolean)field(a,"importing")&&a.resourceIdle());return b[0];});}
 void click(Object o,String n){runOnMainSync(()->{Button b=(Button)field(o,n);check(b.isEnabled(),"Disabled "+n);b.performClick();});}
 String visible(AccessibilityNodeInfo n){if(n==null)return "";String s=n.getText()==null?"":n.getText()+"\n";for(int i=0;i<n.getChildCount();i++)s+=visible(n.getChild(i));return s;}
 boolean tap(AccessibilityNodeInfo n,String label){if(n==null)return false;if(n.getText()!=null&&n.getText().toString().equalsIgnoreCase(label)){while(n!=null){if(n.isClickable())return n.performAction(AccessibilityNodeInfo.ACTION_CLICK);n=n.getParent();}return false;}for(int i=0;i<n.getChildCount();i++)if(tap(n.getChild(i),label))return true;return false;}
 void tap(String s)throws Exception{await(()->visible(getUiAutomation().getRootInActiveWindow()).toLowerCase(Locale.ROOT).contains(s.toLowerCase(Locale.ROOT)));check(tap(getUiAutomation().getRootInActiveWindow(),s),"Cannot click "+s);getUiAutomation().waitForIdle(100,3000);}
 void search(String question,boolean disabled)throws Exception{
  runOnMainSync(()->((EditText)field(a,"question")).setText(question));click(a,"search");ready();check(!a.latestAnswer().invokedModel,"Unexpected model invocation");ResearchEngine.Result r=(ResearchEngine.Result)field(a,"latestEvidence");Set<String> editions=new HashSet<>();
  for(int i=0;i<r.hits.size();i++){ResearchEngine.Passage p=r.hits.get(i).passage;editions.add(p.id.split("_")[0]);if(disabled)check(!p.id.contains("c69f31299553f4a1168eaa0400129fd5e41f21b4354248a0e2b97a87546ff274"),"Disabled source leaked");final int j=i;runOnMainSync(()->((LinearLayout)field(a,"sourceList")).getChildAt(j).performClick());await(()->visible(getUiAutomation().getRootInActiveWindow()).contains(p.text));String text=visible(getUiAutomation().getRootInActiveWindow());check(text.contains(p.id)&&text.contains(p.url)&&text.contains(p.sourceDate)&&text.contains(p.license)&&text.contains(p.collectionProvenance),"Dialog provenance mismatch");String name=(disabled?"disabled-":"combined-")+i;android.graphics.Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"No screenshot");try(FileOutputStream out=new FileOutputStream(new File(root,name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();dialogs.put(new JSONObject().put("file",name+".png").put("citation",p.id).put("disabled_science",disabled).put("visible",text).put("route",a.latestAnswer().kind.name()).put("invoked",false));tap("Close");}
  check(editions.size()==(disabled?1:2),"Unexpected source edition coverage");
 }
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle b=new Bundle();byte[] original=null;File catalog=new File(getTargetContext().getFilesDir(),"pack-library/catalog.json");try{
  root=new File(getTargetContext().getFilesDir(),"multi-pack-source-tests");root.mkdirs();original=Files.readAllBytes(catalog.toPath());getUiAutomation();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));ready();check(a.modelReady(),"Saved model not ready");click(field(a,"nativePanel"),"unload");ready();check(!a.modelReady(),"Unload failed");String q="Explain magma and lava, and why headlamps are recommended.";search(q,false);
  click(a,"collections");tap("science supplement 2026 10 01 v1 · edition c69f3129");tap("Apply");ready();search(q,true);report.put("status","PASS");
 }catch(Throwable e){try{report.put("status","FAIL").put("failure",e.toString());}catch(Exception ignored){}b.putString("failure",e.toString());}
 finally{try{if(a!=null){ready();runOnMainSync(a::finish);}if(original!=null){File stage=new File(root,"restore.json");Files.write(stage.toPath(),original);Files.move(stage.toPath(),catalog.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);check(Arrays.equals(original,Files.readAllBytes(catalog.toPath())),"Catalog restoration failed");}report.put("catalog_restored",true).put("dialogs",dialogs);Files.write(new File(root,"results.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));}catch(Throwable e){b.putString("cleanup_failure",e.toString());}}
 finish(report.optString("status").equals("PASS")?-1:1,b);
 }
}
